import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const configPath = path.join(__dirname, 'config.json');
const outPath = path.join(__dirname, 'config.out.json');

const raw = fs.readFileSync(configPath, 'utf8');
const cfg = raw.trim() ? JSON.parse(raw) : {};

if (cfg.port === undefined) cfg.port = 3000;
if (cfg.host === undefined) cfg.host = '127.0.0.1';

fs.writeFileSync(outPath, JSON.stringify(cfg, null, 2));
console.log('wrote', outPath, JSON.stringify(cfg));
